import{_ as a,H as e,f as r,i as t}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"PIGLIN KING エピローグ 最後のページ","description":"","frontmatter":{"title":"PIGLIN KING エピローグ 最後のページ","outline":"deep"},"headers":[],"relativePath":"story/epilogue.md","filePath":"story/epilogue.md"}'),i={name:"story/epilogue.md"};function o(l,p,n,h,d,s){return e(),r("div",null,[...p[0]||(p[0]=[t('<h1 id="piglin-king" tabindex="-1">PIGLIN KING <a class="header-anchor" href="#piglin-king" aria-label="Permalink to &quot;PIGLIN KING&quot;">​</a></h1><h2 id="エピローグ-最後のページ" tabindex="-1">エピローグ 最後のページ <a class="header-anchor" href="#エピローグ-最後のページ" aria-label="Permalink to &quot;エピローグ 最後のページ&quot;">​</a></h2><hr><h1 id="数百年後" tabindex="-1">数百年後 <a class="header-anchor" href="#数百年後" aria-label="Permalink to &quot;数百年後&quot;">​</a></h1><p>王国歴三八七年。</p><p>春。</p><p>王都 GOLDEN BASTION。</p><p>かつて黄金王が暮らした王都は、</p><p>今や世界最大の都市となっていた。</p><p>空には飛行船が行き交い、</p><p>王立大学は世界中から学者が集まり、</p><p>人々は平和な日々を送っていた。</p><p>そして。</p><p>王立歴史博物館。</p><p>「おじいちゃん！」</p><p>「早くー！」</p><p>一人の少年が走っていた。</p><p>「こらこら。」</p><p>「転ぶよ。」</p><p>白髪の老人が微笑む。</p><p>「今日はね。」</p><p>「すごい人たちを見に来たんだ。」</p><p>「すごい人？」</p><p>「そう。」</p><p>「世界で一番有名な三人さ。」</p><hr><h1 id="英雄たち" tabindex="-1">英雄たち <a class="header-anchor" href="#英雄たち" aria-label="Permalink to &quot;英雄たち&quot;">​</a></h1><p>少年が立ち止まった。</p><p>「わぁ……。」</p><p>巨大な絵。</p><p>黄金の冠。</p><p>豪快な笑顔。</p><p>優しそうな青年。</p><p>眼鏡をかけた学者。</p><p>三人が並んで笑っていた。</p><p>「この人たち誰？」</p><p>老人は微笑んだ。</p><p>「英雄さ。」</p><p>「PIGLIN KINGDOMを作った人たち。」</p><p>「真ん中の人は？」</p><p>「KING PIGLIN I。」</p><p>「オーレックス・ゴールドタスク。」</p><p>「黄金王と呼ばれた。」</p><p>「優しい王様だったんだ。」</p><p>「左の人は？」</p><p>「スターリン。」</p><p>「世界一騒がしい英雄だ。」</p><p>「右の人は？」</p><p>「ピックバーグ。」</p><p>「世界一賢い学者だった。」</p><p>少年は目を輝かせた。</p><p>「すごい！」</p><p>「会ってみたかったなぁ！」</p><p>老人は優しく笑った。</p><p>「きっと。」</p><p>「君のことを気に入っただろうね。」</p><p>「本当？」</p><p>「本当さ。」</p><p>「スターリンは一緒に遊んでくれただろう。」</p><p>「ピックバーグは本を読んでくれただろう。」</p><p>「そして。」</p><p>「黄金王は。」</p><p>「きっと優しく笑ってくれただろう。」</p><hr><h1 id="春風" tabindex="-1">春風 <a class="header-anchor" href="#春風" aria-label="Permalink to &quot;春風&quot;">​</a></h1><p>その時。</p><p>窓から、</p><p>暖かな春風が吹いた。</p><p>花びらが舞う。</p><p>「わっ！」</p><p>少年は笑った。</p><p>「風だ！」</p><p>老人は空を見上げた。</p><p>青空。</p><p>白い雲。</p><p>そして。</p><p>どこからか。</p><p>『おーい！』</p><p>『待て待てー！』</p><p>『君たち、走らない！』</p><p>楽しそうな笑い声が、</p><p>聞こえたような気がした。</p><p>老人は小さく笑った。</p><p>「はは。」</p><p>「今でも。」</p><p>「仲良くやってるんだろうな。」</p><hr><h1 id="歴史" tabindex="-1">歴史 <a class="header-anchor" href="#歴史" aria-label="Permalink to &quot;歴史&quot;">​</a></h1><p>歴史とは。</p><p>王の名前ではない。</p><p>戦争の記録でもない。</p><p>偉業だけでもない。</p><p>誰かを想う心。</p><p>友を信じる心。</p><p>家族を愛する心。</p><p>笑い合った日々。</p><p>その全てが、</p><p>歴史になる。</p><p>そして。</p><p>その想いは、</p><p>時代を越えて受け継がれていく。</p><hr><h1 id="最後のページ" tabindex="-1">最後のページ <a class="header-anchor" href="#最後のページ" aria-label="Permalink to &quot;最後のページ&quot;">​</a></h1><p>遠い昔。</p><p>一人の若いピグリンがいた。</p><p>王になる予定などなかった。</p><p>世界を救うつもりもなかった。</p><p>ただ。</p><p>大切な人たちと、</p><p>笑って生きていたかった。</p><p>その願いは。</p><p>親友たちと出会い。</p><p>仲間たちと歩み。</p><p>家族を得て。</p><p>国となり。</p><p>歴史となった。</p><p>そして。</p><p>伝説になった。</p><hr><p>春風が吹く。</p><p>花が揺れる。</p><p>空は青い。</p><p>世界は今日も平和だった。</p><p>それこそが。</p><p>彼らが命をかけて守ったもの。</p><p>そして。</p><p>彼らが、</p><p>最後にたどり着いた答えだった。</p><hr><p>ありがとう。</p><p>黄金王。</p><p>ありがとう。</p><p>スターリン。</p><p>ありがとう。</p><p>ピックバーグ。</p><hr><p>PIGLIN KING</p><p>エピローグ 最後のページ</p><p>完結</p><hr><p>Fin.</p><h3 id="long-live-piglin-kingdom" tabindex="-1">&quot;Long Live PIGLIN KINGDOM.&quot; <a class="header-anchor" href="#long-live-piglin-kingdom" aria-label="Permalink to &quot;&quot;Long Live PIGLIN KINGDOM.&quot;&quot;">​</a></h3><p>👑</p>',143)])])}const c=a(i,[["render",o]]);export{u as __pageData,c as default};
